<?php
require_once __DIR__ . '/includes/functions.php';
$page_title='Semua Kegiatan'; $active_page='activities';
$q=trim($_GET['q']??''); $category=trim($_GET['category']??'all'); $date=trim($_GET['date']??'');
$where=['1=1']; $params=[];
if($q!==''){$where[]='(a.title LIKE :q1 OR a.description LIKE :q2 OR a.location LIKE :q3 OR a.category LIKE :q4)';foreach([':q1',':q2',':q3',':q4'] as $key)$params[$key]='%'.$q.'%';}
if($category!=='all'&&$category!==''){$where[]='a.category=:category';$params[':category']=$category;}
if($date!==''&&valid_date($date)){$where[]='a.activity_date=:date';$params[':date']=$date;}
$sql='SELECT a.*,u.name AS user_name,u.department AS user_department,(SELECT p.id FROM activity_photos p WHERE p.activity_id=a.id ORDER BY p.id ASC LIMIT 1) AS cover_photo_id,(SELECT COUNT(*) FROM activity_photos p2 WHERE p2.activity_id=a.id) AS photo_count FROM activities a JOIN users u ON u.id=a.user_id WHERE '.implode(' AND ',$where).' ORDER BY a.activity_date DESC,a.activity_time DESC,a.id DESC';
$stmt=db()->prepare($sql);$stmt->execute($params);$activities=$stmt->fetchAll();
$categories=['Administrasi','Development','Meeting','Design','Research','Testing','Dokumentasi','Training','Pelayanan','Lapangan','Lainnya'];
require __DIR__ . '/partials/header.php';
?>
<section class="public-hero"><div class="public-hero-copy"><span class="eyebrow">WORKSPACE KEGIATAN INSTANSI</span><h2>Semua kegiatan, <em>tercatat rapi.</em></h2><p>Jelajahi catatan kegiatan, tanggal, kategori, lokasi, dan kontributor. Foto dokumentasi tersedia setelah kamu masuk atau membuat akun.</p><div class="public-hero-actions"><?php if(is_logged_in()): ?><a href="activity_form.php" class="btn btn-primary">＋ Catat kegiatan</a><a href="gallery.php" class="btn btn-secondary">Buka galeri foto</a><?php else: ?><a href="register.php" class="btn btn-primary">Buat akun gratis <span>→</span></a><a href="login.php" class="btn btn-secondary">Sudah punya akun?</a><?php endif; ?></div></div><div class="public-hero-visual"><div class="public-hero-orb orb-a"></div><div class="public-hero-orb orb-b"></div><div class="public-hero-mini"><span class="mini-icon">✓</span><div><strong>Aktivitas terdokumentasi</strong><small>Catatan · Tanggal · Kontributor</small></div></div><div class="public-hero-mini second"><span class="mini-icon photo-icon">▧</span><div><strong>Galeri kegiatan terjaga</strong><small>Foto khusus anggota</small></div></div></div></section>
<div class="section-head page-head"><div><h2>Aktivitas Instansi</h2><p>Jelajahi kegiatan terbaru dan gunakan filter kategori atau tanggal.</p></div><?php if(is_logged_in()): ?><a href="export_csv.php?<?= e(http_build_query($_GET)) ?>" class="btn btn-secondary">⇩ Export CSV</a><?php endif; ?></div>
<form class="filter-box" method="get"><div class="search-input"><span>⌕</span><input name="q" value="<?= e($q) ?>" placeholder="Cari judul, catatan, lokasi, atau kategori..."></div><select name="category"><option value="all">Semua kategori</option><?php foreach($categories as $cat): ?><option value="<?= e($cat) ?>" <?= $category===$cat?'selected':'' ?>><?= e($cat) ?></option><?php endforeach; ?></select><input type="date" name="date" value="<?= e($date) ?>"><button class="btn btn-secondary" type="submit">Filter</button><a href="activities.php" class="btn btn-ghost">Reset</a></form>
<div class="result-head"><span><?= count($activities) ?> kegiatan ditemukan</span><?php if($q||$category!=='all'||$date): ?><span class="filter-active">Filter aktif</span><?php endif; ?></div>
<div class="activity-card-grid">
<?php if(!$activities): ?><div class="empty wide"><strong>Belum ada kegiatan yang cocok.</strong><span>Ubah filter atau tambahkan dokumentasi kegiatan baru.</span></div><?php endif; ?>
<?php foreach($activities as $activity): $canManage=can_manage_activity($activity); ?>
<article class="activity-card"><a class="card-media card-media-link" href="activity_view.php?id=<?= (int)$activity['id'] ?>"><?php if($activity['cover_photo_id'] && is_logged_in()): ?><img src="<?= e(photo_url((int)$activity['cover_photo_id'])) ?>" alt="Foto <?= e($activity['title']) ?>"><span class="photo-badge">📷 <?= (int)$activity['photo_count'] ?> foto</span><?php elseif($activity['cover_photo_id']): ?><div class="locked-cover"><span class="locked-cover-icon">⌑</span><strong><?= (int)$activity['photo_count'] ?> foto dokumentasi</strong><small>Login untuk melihat foto ↗</small></div><?php else: ?><div class="no-photo"><span>◎</span><small>Belum ada foto</small></div><?php endif; ?></a>
<div class="card-body"><div class="card-top"><span class="tag"><?= e($activity['category']) ?></span><span class="tag tag-date"><?= e(format_date_id($activity['activity_date'])) ?></span></div><h3><a href="activity_view.php?id=<?= (int)$activity['id'] ?>"><?= e($activity['title']) ?></a></h3><div class="meta-line"><span>◷ <?= e($activity['activity_time']?format_time($activity['activity_time']):'Tanpa waktu') ?></span><?php if($activity['location']): ?><span>⌖ <?= e($activity['location']) ?></span><?php endif; ?></div><p><?= e($activity['description']?:'Tidak ada catatan tambahan.') ?></p><div class="contributor-line"><div class="avatar tiny avatar-image"><img src="<?= e(avatar_url((int)$activity['user_id'])) ?>" alt=""></div><div><strong><a href="user_profile.php?id=<?= (int)$activity['user_id'] ?>"><?= e($activity['user_name']) ?></a></strong><small><?= e($activity['user_department']?:'Anggota instansi') ?></small></div></div><div class="card-actions"><a class="btn btn-mini" href="activity_view.php?id=<?= (int)$activity['id'] ?>">Lihat detail</a><?php if($canManage): ?><a class="btn btn-mini" href="activity_form.php?id=<?= (int)$activity['id'] ?>">Edit</a><form method="post" action="activity_delete.php" class="inline-form" onsubmit="return confirm('Hapus kegiatan ini beserta seluruh fotonya?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$activity['id'] ?>"><button class="btn btn-mini danger" type="submit">Hapus</button></form><?php endif; ?></div></div></article>
<?php endforeach; ?></div>
<?php require __DIR__ . '/partials/footer.php'; ?>
